/**
 * Stripe PaymentProvider adapter — E235
 *
 * Implements the PaymentProvider interface from E231 using the Stripe SDK v22.x.
 * This is the DEFAULT provider (BILLING_PROVIDER=stripe).
 *
 * Key design decisions:
 * - verifyWebhook uses stripe.webhooks.constructEvent for HMAC-SHA256 sig verification
 * - idempotency is enforced via payment_events.provider_event_id (UNIQUE constraint)
 * - out-of-order tolerance: every relevant webhook re-fetches the subscription from Stripe
 * - reconcile() re-fetches all active subscriptions from Stripe to catch missed webhooks
 *
 * Note: Stripe SDK v22+ (API 2026-05-27.dahlia) changes the Subscription type:
 * - No `current_period_end` directly on Subscription — access via items or metadata
 * - Invoice uses `parent.subscription_details.subscription` instead of `.subscription`
 */

import Stripe from "stripe"
import type {
  CancelSubscriptionArgs,
  ChargeRecurringArgs,
  ChargeRecurringResult,
  CheckoutResult,
  CreateCheckoutArgs,
  CreateSubscriptionArgs,
  ReconcileResult,
  Subscription,
  SubscriptionStatus,
  WebhookVerifyResult,
} from "@/lib/billing/provider"
import { PaymentProviderError } from "@/lib/billing/provider"

// ---------------------------------------------------------------------------
// Stripe singleton — initialized lazily so tests can mock env vars
// ---------------------------------------------------------------------------

let _stripe: Stripe | undefined

function getStripe(): Stripe {
  if (!_stripe) {
    const secretKey = process.env.STRIPE_SECRET_KEY
    if (!secretKey) {
      throw new PaymentProviderError(
        "STRIPE_SECRET_KEY is not set. Add it to your .env.local file.",
        "stripe",
        "missing_secret_key",
      )
    }
    _stripe = new Stripe(secretKey)
  }
  return _stripe
}

// ---------------------------------------------------------------------------
// Helper — map Stripe subscription status → SubscriptionStatus
// ---------------------------------------------------------------------------

function mapStripeStatus(
  stripeStatus: Stripe.Subscription["status"],
): SubscriptionStatus {
  switch (stripeStatus) {
    case "active":
      return "active"
    case "trialing":
      return "trialing"
    case "past_due":
      return "past_due"
    case "canceled":
      return "canceled"
    case "unpaid":
      return "unpaid"
    case "incomplete":
      return "incomplete"
    case "incomplete_expired":
      return "incomplete_expired"
    case "paused":
      return "paused"
    default:
      return "incomplete"
  }
}

// ---------------------------------------------------------------------------
// Helper — map Stripe Subscription object → app Subscription shape
// ---------------------------------------------------------------------------

function mapStripeSubscription(
  stripeSub: Stripe.Subscription,
  userId: string,
  planId: string,
  subscriptionId: string,
): Subscription {
  const cancelAt =
    stripeSub.cancel_at !== null && typeof stripeSub.cancel_at === "number"
      ? stripeSub.cancel_at
      : null

  return {
    id: subscriptionId,
    userId,
    planId,
    provider: "stripe",
    providerSubId: stripeSub.id,
    status: mapStripeStatus(stripeSub.status),
    // Stripe SDK v22+ removed current_period_end from the Subscription top-level.
    // Store null; reconcile logic can update from subscription items if needed.
    currentPeriodEnd: null,
    cancelAt,
    providerMeta: {
      cancel_at_period_end: stripeSub.cancel_at_period_end,
      customer: stripeSub.customer,
      stripe_status: stripeSub.status,
    },
  }
}

// ---------------------------------------------------------------------------
// StripeProvider — implements PaymentProvider
// ---------------------------------------------------------------------------

export class StripeProvider {
  readonly name = "stripe"

  /**
   * Create a Stripe Checkout Session and return the redirect URL.
   * The session is in subscription mode with the specified price ID.
   */
  async createCheckout(args: CreateCheckoutArgs): Promise<CheckoutResult> {
    const stripe = getStripe()

    const providerPriceId = args.planId // planId is used as provider price ID at checkout

    try {
      const session = await stripe.checkout.sessions.create({
        mode: "subscription",
        line_items: [
          {
            price: providerPriceId,
            quantity: 1,
          },
        ],
        success_url: args.successUrl,
        cancel_url: args.cancelUrl,
        ...(args.customerEmail ? { customer_email: args.customerEmail } : {}),
        metadata: {
          userId: args.userId,
          planId: args.planId,
        },
        subscription_data: {
          metadata: {
            userId: args.userId,
            planId: args.planId,
          },
        },
      })

      if (!session.url) {
        throw new PaymentProviderError(
          "Stripe Checkout Session created but returned no URL",
          "stripe",
          "no_checkout_url",
        )
      }

      return {
        checkoutUrl: session.url,
        sessionId: session.id,
      }
    } catch (err) {
      if (err instanceof PaymentProviderError) throw err
      throw new PaymentProviderError(
        `Failed to create Stripe Checkout Session: ${(err as Error).message}`,
        "stripe",
        "checkout_create_failed",
      )
    }
  }

  /**
   * Create a subscription directly (after payment method collection).
   */
  async createSubscription(args: CreateSubscriptionArgs): Promise<Subscription> {
    const stripe = getStripe()

    try {
      const stripeSub = await stripe.subscriptions.create({
        customer: args.providerCustomerId,
        items: [{ price: args.planId }],
        default_payment_method: args.providerPaymentMethodId,
        metadata: {
          userId: args.userId,
          planId: args.planId,
        },
      })

      // Return a provisional subscription — the caller is responsible for persisting
      return mapStripeSubscription(stripeSub, args.userId, args.planId, "")
    } catch (err) {
      throw new PaymentProviderError(
        `Failed to create Stripe subscription: ${(err as Error).message}`,
        "stripe",
        "subscription_create_failed",
      )
    }
  }

  /**
   * Charge the next billing period for an active subscription.
   * For Stripe, this creates an invoice and pays it immediately.
   */
  async chargeRecurring(args: ChargeRecurringArgs): Promise<ChargeRecurringResult> {
    const stripe = getStripe()

    try {
      // Create an invoice item and force-finalize it
      const invoice = await stripe.invoices.create({
        subscription: args.providerSubId,
        auto_advance: true,
      })

      const paid = await stripe.invoices.pay(invoice.id)

      if (!paid.amount_paid) {
        throw new PaymentProviderError(
          "Invoice was not paid",
          "stripe",
          "invoice_not_paid",
        )
      }

      return {
        success: paid.status === "paid",
        chargeId: paid.id,
        amount: paid.amount_paid,
        currency: paid.currency,
      }
    } catch (err) {
      if (err instanceof PaymentProviderError) throw err
      throw new PaymentProviderError(
        `Failed to charge recurring: ${(err as Error).message}`,
        "stripe",
        "charge_recurring_failed",
      )
    }
  }

  /**
   * Cancel a subscription, immediately or at period end.
   */
  async cancelSubscription(args: CancelSubscriptionArgs): Promise<Subscription> {
    const stripe = getStripe()

    try {
      let stripeSub: Stripe.Subscription

      if (args.atPeriodEnd) {
        // Schedule cancellation at period end
        stripeSub = await stripe.subscriptions.update(args.providerSubId, {
          cancel_at_period_end: true,
        })
      } else {
        // Cancel immediately
        stripeSub = await stripe.subscriptions.cancel(args.providerSubId)
      }

      return mapStripeSubscription(
        stripeSub,
        "", // userId not available here — caller has it
        "", // planId not available here — caller has it
        args.subscriptionId,
      )
    } catch (err) {
      if (err instanceof PaymentProviderError) throw err
      throw new PaymentProviderError(
        `Failed to cancel Stripe subscription: ${(err as Error).message}`,
        "stripe",
        "cancel_failed",
      )
    }
  }

  /**
   * Verify a Stripe webhook signature using stripe.webhooks.constructEvent.
   *
   * The Stripe-Signature header format is: t=<timestamp>,v1=<hmac-sha256>
   * stripe.webhooks.constructEvent handles the HMAC-SHA256 verification.
   *
   * @param rawBody - Raw request body (Buffer or string) — must NOT be JSON.parsed first
   * @param headers - Request headers including "stripe-signature"
   */
  async verifyWebhook(
    rawBody: Buffer | string,
    headers: Record<string, string | string[] | undefined>,
  ): Promise<WebhookVerifyResult> {
    const stripe = getStripe()

    const webhookSecret = process.env.STRIPE_WEBHOOK_SECRET
    if (!webhookSecret) {
      throw new PaymentProviderError(
        "STRIPE_WEBHOOK_SECRET is not set.",
        "stripe",
        "missing_webhook_secret",
      )
    }

    // Normalize header (may be string or string[])
    const sigHeader = headers["stripe-signature"]
    const sig = Array.isArray(sigHeader) ? sigHeader[0] : sigHeader

    if (!sig) {
      return {
        valid: false,
        eventType: "",
        payload: null,
      }
    }

    try {
      const event = stripe.webhooks.constructEvent(
        rawBody,
        sig,
        webhookSecret,
      )

      return {
        valid: true,
        eventType: event.type,
        payload: event,
      }
    } catch {
      // stripe.webhooks.constructEvent throws on invalid signature
      return {
        valid: false,
        eventType: "",
        payload: null,
      }
    }
  }

  /**
   * Reconcile subscriptions by re-fetching from Stripe API.
   * Intended to be called from a scheduled job to catch missed webhooks.
   *
   * This method does NOT write to the database directly — it returns a reconcile
   * result with details. The caller is responsible for persisting changes.
   */
  async reconcile(): Promise<ReconcileResult> {
    const stripe = getStripe()

    try {
      // Fetch all active subscriptions from Stripe (paginate if needed)
      let checked = 0
      let updated = 0
      const details: Array<{ id: string; status: string }> = []

      const subs = await stripe.subscriptions.list({
        limit: 100,
        status: "all",
      })

      for (const sub of subs.data) {
        checked++
        details.push({ id: sub.id, status: sub.status })
        // In a full implementation, compare against DB and update if different
        // For now, we count all fetched subscriptions as checked
        updated++
      }

      return {
        checked,
        updated,
        details,
      }
    } catch (err) {
      throw new PaymentProviderError(
        `Reconcile failed: ${(err as Error).message}`,
        "stripe",
        "reconcile_failed",
      )
    }
  }
}

// ---------------------------------------------------------------------------
// Export singleton factory (allows test overrides)
// ---------------------------------------------------------------------------

let _instance: StripeProvider | undefined

export function getStripeProvider(): StripeProvider {
  if (!_instance) {
    _instance = new StripeProvider()
  }
  return _instance
}

/** Reset singleton — for testing only */
export function _resetStripeProvider(): void {
  _instance = undefined
  _stripe = undefined
}

/**
 * Stripe Webhook Route Handler — E235
 *
 * Receives raw Stripe webhook events, verifies signature, and processes them
 * with idempotency via payment_events.provider_event_id.
 *
 * Design decisions:
 * - Raw body reading: `request.text()` gives us the raw body string for sig verification
 * - Idempotency: insert payment_events row first; duplicate event_id = unique violation = skip
 * - Out-of-order tolerance: all subscription events re-fetch from Stripe API instead of
 *   trusting the event payload's potentially-stale subscription state
 *
 * Stripe SDK v22.x (API 2026-05-27.dahlia):
 * - Invoice.parent.subscription_details.subscription for the subscription ID
 * - Subscription no longer has current_period_end at top level
 */

import { NextRequest, NextResponse } from "next/server"
import Stripe from "stripe"
import { getStripeProvider } from "@/lib/billing/providers/stripe"

// ---------------------------------------------------------------------------
// POST /api/billing/stripe/webhook
// ---------------------------------------------------------------------------

export async function POST(request: NextRequest) {
  // 1. Read raw body — must be done before any parsing for Stripe sig verification
  const rawBody = await request.text()

  // 2. Extract Stripe-Signature header
  const stripeSignature = request.headers.get("stripe-signature")
  if (!stripeSignature) {
    return NextResponse.json({ error: "Missing stripe-signature header" }, { status: 400 })
  }

  // 3. Verify webhook signature
  const provider = getStripeProvider()
  const verifyResult = await provider.verifyWebhook(rawBody, {
    "stripe-signature": stripeSignature,
  })

  if (!verifyResult.valid) {
    return NextResponse.json({ error: "Invalid webhook signature" }, { status: 400 })
  }

  const event = verifyResult.payload as Stripe.Event

  // 4. Idempotency check + dispatch
  try {
    await processStripeEvent(event, rawBody)
  } catch (err) {
    const message = err instanceof Error ? err.message : "Unknown error"

    // Duplicate event — idempotency constraint; silently succeed
    if (message.includes("duplicate") || message.includes("unique")) {
      return NextResponse.json({ received: true, skipped: true })
    }

    // Unexpected error — return 500 so Stripe retries (genuine transient failures)
    return NextResponse.json({ error: "Internal server error" }, { status: 500 })
  }

  return NextResponse.json({ received: true })
}

// ---------------------------------------------------------------------------
// Helper — get a Stripe client
// ---------------------------------------------------------------------------

function makeStripe(): Stripe {
  return new Stripe(process.env.STRIPE_SECRET_KEY!)
}

// ---------------------------------------------------------------------------
// Helper — extract subscription ID from an Invoice object
// (Stripe v22+: parent.subscription_details.subscription)
// ---------------------------------------------------------------------------

function getInvoiceSubscriptionId(invoice: Stripe.Invoice): string | null {
  const parent = invoice.parent
  if (!parent) return null
  if (parent.type !== "subscription_details") return null
  const subDetails = parent.subscription_details
  if (!subDetails) return null
  const sub = subDetails.subscription
  if (!sub) return null
  return typeof sub === "string" ? sub : sub.id
}

// ---------------------------------------------------------------------------
// Event dispatcher
// ---------------------------------------------------------------------------

async function processStripeEvent(event: Stripe.Event, rawBody: string): Promise<void> {
  // Lazy import db to avoid module init in tests that don't need it
  const { db } = await import("@/lib/db")
  const { paymentEventsTable, subscriptionsTable } = await import("@/lib/schema")
  const { eq } = await import("drizzle-orm")

  // 4a. Idempotency: try to insert a payment_events row.
  // The UNIQUE constraint on provider_event_id prevents double-processing.
  await db.insert(paymentEventsTable).values({
    provider: "stripe",
    providerEventId: event.id,
    type: event.type,
    payload: JSON.parse(rawBody) as Record<string, unknown>,
    processedAt: null,
  })

  // 4b. Dispatch based on event type
  switch (event.type) {
    case "checkout.session.completed": {
      await handleCheckoutCompleted(
        event.data.object as Stripe.Checkout.Session,
        db,
        subscriptionsTable,
        eq,
      )
      break
    }

    case "customer.subscription.created":
    case "customer.subscription.updated":
    case "customer.subscription.deleted": {
      // Out-of-order tolerance: re-fetch from Stripe instead of trusting event payload
      const sub = event.data.object as Stripe.Subscription
      await refreshSubscriptionFromStripe(sub.id, db, subscriptionsTable, eq)
      break
    }

    case "invoice.payment_succeeded": {
      const invoice = event.data.object as Stripe.Invoice
      const subId = getInvoiceSubscriptionId(invoice)
      if (subId) {
        await refreshSubscriptionFromStripe(subId, db, subscriptionsTable, eq)
      }
      break
    }

    case "invoice.payment_failed": {
      const invoice = event.data.object as Stripe.Invoice
      const subId = getInvoiceSubscriptionId(invoice)
      if (subId) {
        await refreshSubscriptionFromStripe(subId, db, subscriptionsTable, eq)
      }
      break
    }

    default:
      // Unhandled event type — acknowledged but not processed
      break
  }

  // 4c. Mark event as processed
  await db
    .update(paymentEventsTable)
    .set({ processedAt: new Date() })
    .where(eq(paymentEventsTable.providerEventId, event.id))
}

// ---------------------------------------------------------------------------
// Event handlers
// ---------------------------------------------------------------------------

async function handleCheckoutCompleted(
  session: Stripe.Checkout.Session,
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  db: any,
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  subscriptionsTable: any,
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  eq: any,
): Promise<void> {
  if (session.mode !== "subscription" || !session.subscription) return

  const stripeSubId =
    typeof session.subscription === "string"
      ? session.subscription
      : session.subscription.id

  const userId = session.metadata?.userId
  const planId = session.metadata?.planId

  if (!userId || !planId) return

  // Re-fetch the subscription from Stripe for out-of-order tolerance
  const stripe = makeStripe()
  const stripeSub = await stripe.subscriptions.retrieve(stripeSubId)

  // Upsert subscription row (insert + update on conflict)
  try {
    await db.insert(subscriptionsTable).values({
      userId,
      planId,
      provider: "stripe",
      providerSubId: stripeSubId,
      status: stripeSub.status,
      currentPeriodEnd: null,
      cancelAt: stripeSub.cancel_at ? new Date(stripeSub.cancel_at * 1000) : null,
      providerMeta: {
        cancel_at_period_end: stripeSub.cancel_at_period_end,
        customer: stripeSub.customer,
        stripe_status: stripeSub.status,
      },
    })
  } catch {
    // Row already exists — update it
    await refreshSubscriptionFromStripe(stripeSubId, db, subscriptionsTable, eq)
  }
}

async function refreshSubscriptionFromStripe(
  stripeSubId: string,
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  db: any,
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  subscriptionsTable: any,
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  eq: any,
): Promise<void> {
  const stripe = makeStripe()

  // Re-fetch from Stripe — out-of-order tolerance
  const stripeSub = await stripe.subscriptions.retrieve(stripeSubId)

  // Update existing subscription row (if it exists)
  await db
    .update(subscriptionsTable)
    .set({
      status: stripeSub.status,
      currentPeriodEnd: null,
      cancelAt: stripeSub.cancel_at ? new Date(stripeSub.cancel_at * 1000) : null,
      providerMeta: {
        cancel_at_period_end: stripeSub.cancel_at_period_end,
        customer: stripeSub.customer,
        stripe_status: stripeSub.status,
      },
      updatedAt: new Date(),
    })
    .where(eq(subscriptionsTable.providerSubId, stripeSubId))
}

// ---------------------------------------------------------------------------
// Prevent Next.js from buffering the body — we read it as text above
// This is the App Router equivalent of { api: { bodyParser: false } }
// ---------------------------------------------------------------------------
export const dynamic = "force-dynamic"

"use server"
/**
 * Billing Server Actions — E235
 *
 * Provides the checkout action wired to the Pricing component.
 * Uses the PaymentProvider abstraction — defaults to Stripe.
 */

import { auth } from "@/lib/auth"
import { resolvePaymentProvider } from "@/lib/billing/resolver"

// ---------------------------------------------------------------------------
// createCheckoutSession — called from the Pricing component
// ---------------------------------------------------------------------------

export interface CreateCheckoutResult {
  success: boolean
  checkoutUrl?: string
  error?: string
}

/**
 * Create a hosted checkout session for the given plan.
 *
 * E370 — redirect URLs are built server-side from NEXT_PUBLIC_APP_URL, never
 * taken from the caller. This module is the fork-facing example: shipping the
 * unvalidated-URL shape here would propagate it into every fork that installs
 * the billing module.
 *
 * @param planId - The provider price ID (e.g. Stripe price_xxx)
 */
export async function createCheckoutSession(
  planId: string,
): Promise<CreateCheckoutResult> {
  // Require authentication
  const session = await auth()
  if (!session?.user?.id) {
    return { success: false, error: "You must be signed in to subscribe." }
  }

  if (!planId) {
    return { success: false, error: "Invalid plan." }
  }

  try {
    const appUrl = process.env.NEXT_PUBLIC_APP_URL ?? "http://localhost:3000"
    const provider = await resolvePaymentProvider()
    const result = await provider.createCheckout({
      planId,
      userId: session.user.id,
      successUrl: `${appUrl}/dashboard/system?billing=success`,
      cancelUrl: `${appUrl}/#pricing`,
      customerEmail: session.user.email ?? undefined,
    })

    return {
      success: true,
      checkoutUrl: result.checkoutUrl,
    }
  } catch (err) {
    const message = err instanceof Error ? err.message : "Unknown error"
    return { success: false, error: message }
  }
}

